!function(){"use strict";app.factory("articuloService",(function(mainService){let url="Articulo/";return{search:function(query){return mainService.getData("get",url+query).hen(response=>{})},findForPurchase:function(query){return mainService.getData("get",url+"FindForPurchase?json="+JSON.stringify(query),null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let dataRepository=JSON.parse(response.payload),dataArticulo=dataRepository[0][0],medidas=dataRepository[1]||[],etiquetas=dataRepository[2]||[],articuloMapper,medidasMapper,etiquetasMapper;return{articulo:{codIce:dataArticulo.codIce,codImpuesto:dataArticulo.codImpuesto,codigoArticulo:dataArticulo.codigoArticulo,codigoAuxiliar:dataArticulo.codigoAuxiliar,codigoPorcentaje:dataArticulo.codigoPorcentaje,codigoPrincipal:dataArticulo.codigoPrincipal,costoNeto:dataArticulo.costoNeto,datosAdicionales:dataArticulo.datosAdicionales,descripcion:dataArticulo.descripcion,idArticulo:dataArticulo.idArticulo,idTipoIva:dataArticulo.idTipoIva,llevaInventario:dataArticulo.llevaInventario,nombreTipoIva:dataArticulo.nombreTipoIva,productoFraccionable:dataArticulo.productoFraccionable,stock:dataArticulo.stock,tarifa:dataArticulo.tarifa,valorIce:dataArticulo.valorIce},medidas:medidas.map(item=>({idMedida:item.idMedida,descripcion:item.descripcion,precioCosto:item.precioCosto})),etiquetas:etiquetas.map(item=>({idEtiqueta:item.idEtiqueta,descripcion:item.descripcion,etiquetas:item.etiquetas.split(";")}))}}})},findForSale:function(query){return mainService.getData("get",url+"FindForSale/"+JSON.stringify(query),null,!0).then(response=>{if("0"===response.code)throw response;"1"===response.code&&console.log(response)})}}}))}(window.angular);